const body = $input.item.json.body || $input.item.json;
const binary = $input.item.binary || {};

// Helper
const get = (key) => body[key] ?? '';

// Handle disciplines including "Other"
const discipline = get('discipline');
const otherDiscipline = get('discipline_other');
const finalDiscipline = (discipline === 'Other' && otherDiscipline) 
  ? otherDiscipline 
  : discipline;

// Work preferences may be array (from multi-checkbox) or comma-string
let workPrefs = get('work_preferences');
if (Array.isArray(workPrefs)) workPrefs = workPrefs.join(', ');

// Consent check (form sends 'yes' if ticked)
const consent = get('consent');
const consented = consent === 'yes' || consent === true;

// Candidate ID
const candidateId = 'CAND-' + Date.now().toString(36).toUpperCase();

// CV file detection — multipart form sends file as binary under cv_file
const cvBinaryKey = Object.keys(binary).find(k => /cv|resume/i.test(k));
const cvBinary = cvBinaryKey ? binary[cvBinaryKey] : null;

// Legacy base64 path (in case form ever changes to JSON+base64)
const cvBase64Field = get('cv_base64');

let cvFilename = '';
let cvMimeType = '';
let cvPresent = false;

if (cvBinary) {
  cvFilename = cvBinary.fileName || 'cv.pdf';
  cvMimeType = cvBinary.mimeType || 'application/pdf';
  cvPresent = true;
} else if (cvBase64Field) {
  cvFilename = get('cv_filename') || 'cv.pdf';
  cvMimeType = get('cv_mime_type') || 'application/pdf';
  cvPresent = true;
}

// Compose full name
const firstName = get('first_name');
const lastName = get('last_name');
const fullName = `${firstName} ${lastName}`.trim();

const out = {
  json: {
    candidate_id: candidateId,
    submitted_at: new Date().toISOString(),
    first_name: firstName,
    last_name: lastName,
    full_name: fullName,
    email: get('email'),
    phone: get('phone'),
    location: get('location'),
    work_auth: get('work_auth'),
    years_experience: get('years_experience'),
    discipline: finalDiscipline,
    discipline_raw: discipline,
    other_discipline: otherDiscipline,
    employed_status: get('employed_status'),
    notice_period_weeks: get('notice_period_weeks') || '',
    salary_expectation: get('salary_expectation'),
    work_preferences: workPrefs,
    summary_self: get('summary_self'),
    cv_file_present: cvPresent,
    cv_filename: cvFilename,
    cv_mime_type: cvMimeType,
    cv_base64: cvBase64Field,
    cv_text_pasted: get('cv_text_pasted'),
    linkedin_url: get('linkedin_url'),
    consented: consented
  }
};

// Preserve the binary so downstream nodes can use it
if (cvBinary) {
  out.binary = { [cvBinaryKey]: cvBinary };
}

return out;

const c = $input.item.json;

const cvSection = c.cv_text_pasted && c.cv_text_pasted.length > 50
  ? `CV TEXT PROVIDED:\n${c.cv_text_pasted.substring(0, 8000)}`
  : c.cv_file_present
    ? `CV FILE: ${c.cv_filename} (uploaded to Drive at ${c.cv_drive_url || 'pending'}). The CV content is attached as a document to this message.`
    : c.linkedin_url
      ? `LinkedIn URL provided: ${c.linkedin_url}`
      : `No CV provided. Work from structured form data only.`;

const prompt = `You are screening a candidate registration for an Australian technical recruitment service (Torren Technical). The service covers electronic test engineers, automation/PLC technicians, embedded engineers, industrial trades, construction trades, and adjacent skilled roles.

Produce a structured screening report. Return ONLY a JSON object. Do NOT include code fences. Do NOT include any text before or after the JSON object — no preamble, no summary, no commentary. Begin your response with { and end with }.

{
  "headline": "1-line elevator pitch — role title + years + key skill or specialism",
  "strengths": ["3-5 key strengths inferred from the submission"],
  "concerns_or_gaps": ["any red flags, gaps, or things to clarify"],
  "best_fit_role_types": ["3-5 specific role titles this candidate would suit"],
  "niche_match_score": "integer 1-10, how well they fit Torren's core niches (test/automation/embedded/industrial/trades/construction)",
  "salary_realism": "is their salary expectation realistic for their experience and discipline? (Realistic / High / Low / Cannot assess)",
  "availability_signal": "How quickly could they start, considering notice period and employment status",
  "follow_up_questions": ["3-5 specific things you'd ask in a 15-minute screening call"],
  "recommend_action": "Progress to screening call / Request more info / Decline politely / Hold for matching"
}

CANDIDATE SUBMISSION:
Name: ${c.full_name}
Email: ${c.email}
Phone: ${c.phone}
Location: ${c.location}
Work Authorisation: ${c.work_auth}
Years Experience: ${c.years_experience}
Discipline: ${c.discipline}
Currently Employed: ${c.employed_status}
Notice Period: ${c.notice_period_weeks} weeks
Salary Expectation: ${c.salary_expectation}
Work Preferences: ${c.work_preferences}
LinkedIn: ${c.linkedin_url || 'Not provided'}

Self-Summary:
${c.summary_self}

${cvSection}`;

// Build Anthropic messages array — include CV document if PDF was uploaded
const messages = [];

if (c.cv_file_present && c.cv_base64 && c.cv_mime_type === 'application/pdf') {
  messages.push({
    role: "user",
    content: [
      {
        type: "document",
        source: {
          type: "base64",
          media_type: "application/pdf",
          data: c.cv_base64
        }
      },
      {
        type: "text",
        text: prompt
      }
    ]
  });
} else {
  messages.push({
    role: "user",
    content: prompt
  });
}

return {
  json: {
    ...c,
    cs_model: "claude-haiku-4-5",
    cs_max_tokens: 1500,
    cs_messages: messages
  }
};

const response = $input.item.json;
const upstream = $('Build Candidate Summary Prompt').item.json;
const content = response.content?.[0]?.text || '';

let summary = {};
try {
  // Try to find a JSON object within the response (handles ```json blocks and trailing prose)
  let jsonText = content;

  // Strip code fences
  jsonText = jsonText.replace(/```json\n?/g, '').replace(/```\n?/g, '');

  // Find the first { and matching last }
  const firstBrace = jsonText.indexOf('{');
  if (firstBrace === -1) throw new Error('No JSON object found');

  // Find matching closing brace using bracket counting
  let depth = 0;
  let lastBrace = -1;
  for (let i = firstBrace; i < jsonText.length; i++) {
    if (jsonText[i] === '{') depth++;
    if (jsonText[i] === '}') {
      depth--;
      if (depth === 0) {
        lastBrace = i;
        break;
      }
    }
  }

  if (lastBrace === -1) throw new Error('Unbalanced braces');

  const jsonOnly = jsonText.substring(firstBrace, lastBrace + 1);
  summary = JSON.parse(jsonOnly);
} catch (e) {
  summary = { error: 'parse failed: ' + e.message, raw: content.substring(0, 500) };
}

return {
  json: {
    candidate_id: upstream.candidate_id,
    submitted_at: upstream.submitted_at,
    full_name: upstream.full_name,
    email: upstream.email,
    phone: upstream.phone,
    location: upstream.location,
    work_auth: upstream.work_auth,
    years_experience: upstream.years_experience,
    discipline: upstream.discipline,
    employed_status: upstream.employed_status,
    notice_period_weeks: upstream.notice_period_weeks,
    salary_expectation: upstream.salary_expectation,
    work_preferences: upstream.work_preferences,
    summary_self: upstream.summary_self,
    linkedin_url: upstream.linkedin_url,
    headline: summary.headline || '',
    strengths: Array.isArray(summary.strengths) ? summary.strengths.join('; ') : (summary.strengths || ''),
    concerns_or_gaps: Array.isArray(summary.concerns_or_gaps) ? summary.concerns_or_gaps.join('; ') : (summary.concerns_or_gaps || ''),
    best_fit_role_types: Array.isArray(summary.best_fit_role_types) ? summary.best_fit_role_types.join('; ') : (summary.best_fit_role_types || ''),
    niche_match_score: parseInt(summary.niche_match_score) || 0,
    salary_realism: summary.salary_realism || '',
    availability_signal: summary.availability_signal || '',
    follow_up_questions: Array.isArray(summary.follow_up_questions) ? summary.follow_up_questions.join('; ') : (summary.follow_up_questions || ''),
    recommend_action: summary.recommend_action || '',
    cv_drive_url: upstream.cv_drive_url || '',
    cv_drive_id: upstream.cv_drive_id || '',
    cv_filename: upstream.cv_filename || '',
    cv_mime_type: upstream.cv_mime_type || '',
  }
};

// Single candidate
const candidate = $('Parse Candidate Summary').first().json;

// All hot jobs
const allJobs = $('Read Hot Jobs').all().map(i => i.json);
const hotJobs = allJobs.filter(j => (j.status || '').toLowerCase() === 'hot');

const jobsText = hotJobs.length === 0
  ? 'NO HOT JOBS CURRENTLY IN PIPELINE'
  : hotJobs.map((j, idx) => 
      `Job ${idx + 1} [${j.job_id}]
Role: ${j.role_title}
Company: ${j.company}
Location: ${j.location}
Salary: ${j.salary || 'Not stated'}
Contract: ${j.contract_type || 'Unknown'}
FIFO: ${j.fifo || 'Unknown'}
Description: ${j.niche || ''}
Pain hypothesis: ${j.pain_hypothesis || ''}`
    ).join('\n\n---\n\n');

const prompt = `You are matching a candidate to live job opportunities. Given the candidate profile and the list of currently Hot jobs in the pipeline, pick the TOP 3 best matches.

Return ONLY JSON with no markdown:

{
  "top_matches": [
    {
      "job_id": "the job_id from the list, or null if no matches",
      "role_title": "role title from the job",
      "company": "company from the job",
      "match_score": "integer 1-10",
      "match_reason": "1-2 sentences on why this candidate fits this role",
      "concerns": "1 sentence on potential mismatch concerns, or null"
    }
  ],
  "overall_market_fit": "1 sentence: how strong is this candidate's position in the current AU market?"
}

CANDIDATE PROFILE:
Name: ${candidate.full_name}
Discipline: ${candidate.discipline}
Years experience: ${candidate.years_experience}
Location: ${candidate.location}
Work auth: ${candidate.work_auth}
Salary expectation: ${candidate.salary_expectation}
Work preferences: ${candidate.work_preferences}
Headline: ${candidate.headline}
Strengths: ${candidate.strengths}
Best-fit role types: ${candidate.best_fit_role_types}

LIVE HOT JOBS:
${jobsText}`;

return [{
  json: {
    candidate_id: candidate.candidate_id,
    submitted_at: candidate.submitted_at,
    full_name: candidate.full_name,
    email: candidate.email,
    phone: candidate.phone,
    location: candidate.location,
    work_auth: candidate.work_auth,
    years_experience: candidate.years_experience,
    discipline: candidate.discipline,
    employed_status: candidate.employed_status,
    notice_period_weeks: candidate.notice_period_weeks,
    salary_expectation: candidate.salary_expectation,
    work_preferences: candidate.work_preferences,
    summary_self: candidate.summary_self,
    linkedin_url: candidate.linkedin_url,
    headline: candidate.headline,
    strengths: candidate.strengths,
    concerns_or_gaps: candidate.concerns_or_gaps,
    best_fit_role_types: candidate.best_fit_role_types,
    niche_match_score: candidate.niche_match_score,
    salary_realism: candidate.salary_realism,
    availability_signal: candidate.availability_signal,
    follow_up_questions: candidate.follow_up_questions,
    recommend_action: candidate.recommend_action,
    cv_drive_url: candidate.cv_drive_url,
    cv_drive_id: candidate.cv_drive_id,
    cv_filename: candidate.cv_filename,
    cv_mime_type: candidate.cv_mime_type,
    hot_jobs_count: hotJobs.length,
    match_model: "claude-haiku-4-5",
    match_max_tokens: 1500,
    match_prompt: prompt
  }
}];

const response = $input.item.json;
const upstream = $('Build Match Prompt').item.json;
const content = response.content?.[0]?.text || '';

let matchData = { top_matches: [], overall_market_fit: '' };
try {
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  matchData = JSON.parse(cleaned);
} catch (e) {}

const matches = matchData.top_matches || [];

// Format matches as a readable string for sheets and telegram
const matchesText = matches.length === 0
  ? 'No current matches in pipeline'
  : matches.map((m, i) => 
      `${i + 1}. ${m.role_title} @ ${m.company} (${m.match_score}/10)\n   Why: ${m.match_reason}${m.concerns ? `\n   Concern: ${m.concerns}` : ''}`
    ).join('\n\n');

return {
  json: {
    ...upstream,
    top_matches_text: matchesText,
    top_matches_json: JSON.stringify(matches),
    overall_market_fit: matchData.overall_market_fit || '',
    match_count: matches.length
  }
};

