const item = $input.item.json;
const binary = $input.item.binary || {};

// Path 1 — Binary already present (from multipart form via Normalize)
const fileKey = Object.keys(binary).find(k => /cv|resume/i.test(k));
if (fileKey && binary[fileKey]) {
  const file = binary[fileKey];
  return {
    json: {
      ...item,
      cv_file_present: true,
      cv_filename: file.fileName || item.cv_filename || 'cv.pdf',
      cv_mime_type: file.mimeType || item.cv_mime_type || 'application/pdf'
    },
    binary: {
      cv_data: file
    }
  };
}

// Path 2 — Legacy base64-in-JSON path
if (item.cv_base64) {
  const buffer = Buffer.from(item.cv_base64, 'base64');
  return {
    json: item,
    binary: {
      cv_data: {
        data: buffer.toString('base64'),
        mimeType: item.cv_mime_type || 'application/pdf',
        fileName: item.cv_filename || 'cv.pdf'
      }
    }
  };
}

// Path 3 — No CV
return {
  json: { ...item, cv_file_present: false, cv_drive_url: '', cv_drive_id: '' }
};

const driveResult = $input.item.json;
const original = $('Prep CV Binary').item.json;

// DEBUG: capture what Drive actually returned so we can see it in output
const driveKeys = Object.keys(driveResult);

// Build the Drive URL from whatever fields are available
let cvUrl = '';
if (driveResult.webViewLink) {
  cvUrl = driveResult.webViewLink;
} else if (driveResult.webContentLink) {
  cvUrl = driveResult.webContentLink;
} else if (driveResult.id) {
  // Fallback: construct the URL from the file ID
  cvUrl = `https://drive.google.com/file/d/${driveResult.id}/view`;
}

return {
  json: {
    ...original,
    cv_drive_url: cvUrl,
    cv_drive_id: driveResult.id || '',
    _debug_drive_keys: driveKeys,
    _debug_drive_id: driveResult.id || 'NO_ID',
    _debug_drive_webviewlink: driveResult.webViewLink || 'NO_WEBVIEWLINK'
  }
};
